-- Reviewed additive system DB seed; run serially. No role grants or existing menu overwrites.
BEGIN;
SET @mall_root=(SELECT menu_id FROM sys_menu WHERE parent_id=0 AND path='mall' AND menu_type='M' ORDER BY menu_id LIMIT 1);
SET @mall_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@mall_root AND path='coupon' AND menu_type='C' ORDER BY menu_id LIMIT 1);
SET @mall_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@mall_root AND path='cart' AND menu_type='C' ORDER BY menu_id LIMIT 1);
COMMIT;
